const hosts={local:['Local Host','在当前电脑上管理会话、文件与工具。'],wsl:['WSL Host','让完整后端运行在 WSL 中，桌面窗口连接该 Host。'],ssh:['SSH Host','连接远程机器上的持久 Host，断开连接后会话仍可保留。']};
document.querySelectorAll('[data-host]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-host]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});const h=hosts[button.dataset.host];document.getElementById('host-name').textContent=h[0];document.getElementById('host-description').textContent=h[1]}));
document.querySelectorAll('[data-host]').forEach(b=>b.setAttribute('aria-pressed',String(b.classList.contains('active'))));
document.getElementById('copy-command').addEventListener('click',async event=>{const button=event.currentTarget;try{await navigator.clipboard.writeText('pnpm install\npnpm --dir agent-sidecar install\npnpm tauri dev');button.textContent='已复制 ✓'}catch{button.textContent='请选中上方命令复制'}setTimeout(()=>button.textContent='复制启动命令 ↗',2500)});
